    "একই IP · ১৫ মিনিট": "Same IP · 15 minutes",
    "মেসের কার্যক্রম ও সিস্টেম স্বাস্থ্য": "Hostel activity and system health",
    "মেসভিত্তিক অপারেশনাল সংকেত। এগুলো সম্ভাব্য সমস্যা শনাক্ত করে; কোনো মেসে স্বয়ংক্রিয় পরিবর্তন করে না।": "Hostel-level operational signals that help identify possible issues. They do not make automatic changes to any hostel.",
    "কত দিনের নিষ্ক্রিয়তাকে সতর্কতা ধরবে": "Days of inactivity before a warning",
    "১৪ দিন": "14 days",
    "৬০ দিন": "60 days",
    "শুধু পর্যবেক্ষণ · নতুন মেসে ৪৮ ঘণ্টা ছাড় · ৮+ অপেক্ষমাণ অনুরোধে সতর্কতা · কোনো অটোমেটিক ব্লক নয়": "Monitoring only · 48-hour grace period for new hostels · Warn at 8+ pending requests · No automatic blocks",
    "PostgreSQL-এর বর্তমান মাপ; Supabase Billing Plan-এর পূর্ণ কোটা বা Edge/Egress ব্যবহার নয়।": "Current PostgreSQL measurements; not the full Supabase billing quota or Edge/Egress usage.",
