    "নতুন কোড তৈরি করলে আগের কোডটি বাতিল হবে।": "Generating a new code will invalidate the previous code.",
    "কপি": "Copy",
    "নতুন যুক্ত হওয়ার কোড তৈরি করুন": "Generate a new join code",
