    "নতুন লিংক তৈরি করলে আগেরটি স্বয়ংক্রিয়ভাবে বাতিল হবে।": "Generating a new link will automatically invalidate the previous link.",
    "আমন্ত্রণ লিংক সক্রিয়": "Invitation link active",
    "৭ দিন বৈধ · আগের লিংক বাতিল": "Valid for 7 days · Previous link invalidated",
    "কপি ও শেয়ার করুন": "Copy and share",
    "অ্যাকাউন্ট তৈরি ও ম্যানেজারের অনুমোদনের পর সদস্যপদ চালু হবে।": "Membership becomes active after account creation and manager approval.",
