    "যাচাই করে সদস্যপদ অনুমোদন দিন।": "Review and approve the membership request.",
    "সিদ্ধান্তের নোট": "Decision note",
    "নতুন কোনো অনুরোধ নেই": "There are no new requests.",
    "নতুন সদস্যের অনুরোধ এলে এখানে দেখা যাবে।": "Requests from new members will appear here.",
    "কোনো অতিরিক্ত বার্তা দেওয়া হয়নি।": "No additional message was provided.",
    "অনুমোদন": "Approve",
    "পরিচয় যাচাই করে আবেদন অনুমোদন বা প্রত্যাখ্যান করুন।": "Verify the applicant’s identity, then approve or reject the request.",
    "নিষ্ক্রিয় করার আগে চলমান মিল ও অনুরোধ যাচাই করুন। পুরোনো হিসাব অক্ষত থাকবে।": "Review active meals and requests before deactivation. Previous accounts will remain intact.",
    "আবার সক্রিয়": "Reactivate",
    "এখনো কোনো কাজের মাস পাওয়া যায়নি": "No active work month was found.",
    "বর্তমান বা নির্ধারিত পুরোনো মাস থাকলে এখানে দেখা যাবে।": "The current month or a scheduled previous month will appear here.",
    "অন্য ট্যাব থেকে মাস নির্বাচন করে হিসাব দেখতে পারেন।": "Select a month in another tab to view its accounts.",
    "— এই মাসের হিসাব দেখা যাবে, তবে এন্ট্রি বা সংশোধনের অনুমতি নেই।": "— This month’s accounts can be viewed, but entries and corrections are not allowed.",
    "প্রদানের তারিখ": "Payment date",
    "যে সদস্যের নামে খালার পারিশ্রমিকটি নথিভুক্ত হবে": "Select the member under whose name the staff payment will be recorded.",
    "সদস্য তালিকা পাওয়া যায়নি। তালিকা লোড না হওয়া পর্যন্ত এন্ট্রি করা যাবে না।": "The member list is unavailable. No entry can be made until the list loads.",
    "সম্পাদনা বাতিল": "Cancel editing",
    "নির্বাচিত কাজের মাস": "Selected work month",
    "মোট কার্যকর পারিশ্রমিক": "Total effective payment",
    "কোনো এন্ট্রি নেই": "No entries",
    "এই কাজের মাসে এখনো খালার টাকার কোনো এন্ট্রি দেওয়া হয়নি।": "No staff payment entries have been made for this work month yet.",
    "বন্ধ মাসের হিসাব সবাই দেখতে পারবেন। সম্পাদনা ও পুনরায় চালুর অনুমতি শুধু সেই অ্যাকাউন্টের, যে মাসটি বন্ধ করেছে; অন্য কাউকে আলাদা অনুমতি দেওয়া যায় না।": "Everyone can view closed-month accounts. Only the account that closed the month can edit or reopen it; this permission cannot be assigned to another account.",
    "বন্ধ মাস রিফ্রেশ": "Refresh closed months",
    "সংরক্ষিত মাস পাওয়া যায়নি": "No saved months were found.",
    "কোনো মাস বন্ধ হলে তার closing তথ্য এখানে দেখা যাবে।": "Closing information will appear here after a month is closed.",
    "বন্ধ মাস নির্বাচন করুন": "Select a closed month",
    "মাস বন্ধ করেছেন": "Closed by",
    "আপনার প্রবেশাধিকার": "Your access",
    "শেষ সংশোধন": "Last correction",
    "এই মাসটি শুধু দেখার জন্য": "This month is view-only",
    "সার্ভার থেকে সংশোধনের অনুমতি নিশ্চিত করা যায়নি। নিরাপত্তার জন্য কোনো পরিবর্তন বা Reopen অপশন দেখানো হচ্ছে না।": "The server could not confirm correction permission. Changes and the reopen option are hidden for security.",
    "ভুলবশত বন্ধ হয়ে থাকলে মাস আবার চালু করতে পারবেন": "If the month was closed by mistake, you may be able to reopen it.",
    "শুধু একই calendar month-এ, নতুন period তৈরি না হলে এবং কোনো running period না থাকলে এটি সম্ভব। আগেই বাতিল হওয়া future request স্বয়ংক্রিয়ভাবে ফিরবে না।": "This is possible only within the same calendar month, if no new period has been created and no other period is running. Previously cancelled future requests will not be restored automatically.",
    "মাস আবার চালু করুন": "Reopen month",
    "নিরাপত্তা ও অনুমতি": "Security and permissions",
    "বন্ধ মাসের সম্পাদনা-নিয়ম": "Closed-month editing rules",
    "বন্ধ মাসের জন্য আলাদা Edit Permission দেওয়া, অন্য অ্যাকাউন্টে স্থানান্তর বা Primary Manager override সমর্থিত নয়।": "Separate edit permissions, transfer to another account or a Primary Manager override are not supported for closed months.",
    "প্রতি ঘরে: সকাল + দুপুর + রাত · তারিখের পূর্ণ মাস উপরের শিরোনামে রয়েছে।": "Each cell shows: morning + afternoon + night · The full month for the date appears in the heading above.",
    "সবাই": "Everyone",
    "পিডিএফ সংরক্ষণ": "Save PDF",
    "সদস্যভিত্তিক মোট": "Member-wise total",
    "মোট কার্যকর বাজার": "Total eligible market expenses",
    "কোনো জমার তথ্য নেই": "There are no deposit records.",
    "সর্বমোট জমা": "Total deposits",
    "খালার টাকার মোট": "Total staff payments",
    "সদস্যভিত্তিক ফাইনাল হিসাব": "Member-wise final accounts",
    "বকেয়া/অবশিষ্ট হলো প্রত্যেক সদস্যের নিজস্ব জমা, মিলের খরচ ও অন্যান্য ব্যক্তিগত খরচ অনুযায়ী হিসাব। খালার পারিশ্রমিক সদস্যের ব্যালেন্সে অন্তর্ভুক্ত নয়।": "Due or remaining balance is calculated from each member’s own deposits, meal costs and other personal expenses. Staff payments are not included in a member’s balance.",
    "বাজারের বিবরণ": "Market details",
    "সদস্যভিত্তিক জমা": "Member-wise deposits",
