    "ব্যবহারকারীর সঙ্গে সরাসরি কথা বলে পরিচয় যাচাই করুন। এই কাজের জন্য Supabase-এর নিরাপদ Edge Function Deploy করতে হবে। পুরোনো পাসওয়ার্ড দেখা সম্ভব নয়।": "Verify the user’s identity by speaking with them directly. This action requires a secure Supabase Edge Function deployment. Existing passwords cannot be viewed.",
