    "Trigger শনাক্ত হয়েছে। Dashboard-এর URL ও Header Secret আলাদাভাবে যাচাই করুন—সেগুলোর গোপন মান এখানে পড়া বা প্রকাশ করা হয় না।": "The trigger was detected. Verify the Dashboard URL and header secret separately; their secret values are not read or exposed here.",
