    "আপনার তথ্যের স্বচ্ছ ব্যবহার": "Your information, clearly explained",
    "Hostel Life-এ কোন তথ্য ব্যবহৃত হয়, কেন প্রয়োজন হয় এবং কতদিন রাখা হয়—সহজ ভাষায় জানুন।": "Learn what information Hostel Life uses, why it is needed and how long it is retained.",
    "Hostel Life চালানো, মেসের হিসাব সংরক্ষণ এবং অ্যাকাউন্ট সুরক্ষার জন্য প্রয়োজনীয় তথ্য ব্যবহার করে। কোন তথ্য কী কাজে লাগে, কারা দেখতে পারেন এবং কতদিন রাখা হয়—তা নিচে ব্যাখ্যা করা হয়েছে।": "Hostel Life uses the information needed to operate the service, maintain hostel accounts and protect accounts. The sections below explain what information is used, why it is needed, who can access it and how long it is retained.",
    "তথ্য বা অ্যাকাউন্ট নিয়ে সহায়তা প্রয়োজন?": "Need help with your information or account?",
