    "Hostel Life মেসের দৈনন্দিন ব্যবস্থাপনা, মিল এবং হিসাবের রেকর্ড গুছিয়ে রাখার একটি সেবা। সঠিক তথ্য দেওয়া, নিজের অনুমতির মধ্যে থাকা এবং অন্য ব্যবহারকারীর তথ্যের প্রতি সম্মান দেখানোই এই শর্তগুলোর মূল উদ্দেশ্য।": "Hostel Life helps organise everyday hostel management, meals and account records. These terms are intended to encourage accurate information, respect for permissions and consideration for other users’ information.",
