    /* RUN69_EXTENDED_UI_TRANSLATIONS_1 */
    "AAL2 Token পাওয়া গেছে, কিন্তু অ্যাপের সক্রিয় Session এখনো AAL2 হয়নি। প্যানেল নিরাপদ রাখতে প্রবেশ বন্ধ রাখা হয়েছে।": "An AAL2 token was received, but the app session has not reached AAL2 yet. Access to the panel has been blocked for security.",
    "Activity History সংরক্ষণ শুরু:": "Activity History save started:",
    "Activity Log রিফ্রেশ করা যায়নি। আগের সফল তথ্য রাখা হয়েছে।": "Activity Log could not be refreshed. The last successfully loaded information has been kept.",
    "Activity ও Security operational log-এর লক্ষ্য ৩০ দিন। Run35 cleanup নতুন Activity/Security Event এলে চলে—Supabase-এ scheduler/cron সেটআপ করা না থাকায় নির্দিষ্ট সময়ে cleanup হওয়ার নিশ্চয়তা নেই। Super Admin-এর Platform Audit Log আলাদা accountability record হিসেবে এই ৩০ দিনের purge-এর আওতায় নেই। Password Reset quota হিসাবের HMAC-only row ৩৫ দিন থাকে, যাতে মাসভিত্তিক সীমা সঠিকভাবে গণনা করা যায়। ব্যবহারকারীর আর্থিক/মাসিক archive detail এই ৩০ দিনের log rule দিয়ে মুছে ফেলা হয় না; সেগুলোর আলাদা Summary ও typed-confirmation policy আছে।": "Activity and Security operational logs have a 30-day target retention period. Run35 cleanup runs when a new Activity/Security Event occurs; without a scheduler or cron configured in Supabase, cleanup at a fixed time is not guaranteed. The Super Admin Platform Audit Log is a separate accountability record and is not included in this 30-day purge. HMAC-only rows used for Password Reset quota calculations remain for 35 days to support accurate monthly limits. Users’ financial and monthly archive details are not deleted by this 30-day log rule; they follow a separate summary and typed-confirmation policy.",
