    "Security Gate পরিবর্তন": "Change Security Gate",
    "Security Monitor-এ Login, Registration ও Password Reset-এর Event দেখা যায়। নিরাপত্তার প্রয়োজনে IP, ঘটনার সময়, Request Origin ও Browser তথ্য ব্যবহার করা হয়। নতুন Event-এ দেশ, শহর, অঞ্চল বা GPS অবস্থান সংগ্রহ বা সংরক্ষণ করা হয় না; পুরোনো Event-এ আগে থাকা location তথ্যও এখানে দেখানো হয় না। Password ও OTP সংরক্ষণ করা হয় না। App pre-check সরাসরি Supabase Auth endpoint-এ পাঠানো অনুরোধ আটকাতে পারে না।": "The Security Monitor shows Login, Registration and Password Reset events. For security purposes, it uses IP address, event time, request origin and browser information. New events do not collect or store country, city, region or GPS location; location information already present in older events is not displayed here. Passwords and OTPs are not stored. The app pre-check cannot block requests sent directly to the Supabase Auth endpoint.",
