    "এই অনুরোধে Client IP পাওয়া যায়নি। IP-ভিত্তিক অতিরিক্ত যাচাই বাদ থাকবে; Supabase Auth-এর নিজস্ব নিরাপত্তা চালু আছে।": "No Client IP was available for this request. Additional IP-based verification will be skipped; Supabase Auth’s own security remains enabled.",
    "এই অপশন ON করলে ওই বাজার এন্ট্রির সম্পূর্ণ মোট টাকা নির্বাচিত সদস্যের হিসাবে বাজার-ডিপোজিট হিসেবে যোগ হবে। OFF থাকলে বাজারের মোট টাকা ওই সদস্যের ডিপোজিটে যোগ হবে না। সংরক্ষণের আগে অপশনের ON/OFF অবস্থা ও বাজারকারীর নাম যাচাই করুন।": "When this option is ON, the full amount of that market entry is added to the selected member’s account as a market deposit. When OFF, the market total is not added to that member’s deposit. Before saving, verify the ON/OFF setting and the buyer’s name.",
    "এই অ্যাকাউন্ট ইতিমধ্যে একটি মেসের সঙ্গে যুক্ত আছে।": "This account is already linked to a hostel.",
    "এই অ্যাকাউন্টটি Block করা আছে। Super Admin প্রবেশাধিকার দেওয়া যাচ্ছে না।": "This account is blocked. Super Admin access cannot be granted.",
    "এই অ্যাকাউন্টে নতুন লগইন হওয়ায় এই ডিভাইসের পুরোনো সেশন বন্ধ করা হয়েছে। নিরাপত্তার জন্য আবার লগইন করুন।": "A new login was detected for this account, so the previous session on this device was closed. Sign in again for security.",
    "এই অ্যাকাউন্টে শুধু দেখার অনুমতি আছে। কোনো হিসাব পরিবর্তন করা যাবে না।": "This account has view-only access. Accounts cannot be changed.",
    "এই আবেদনটির প্রতিটি তারিখ এখনো final না হলে পরিবর্তন হবে। তারপর একই আবেদন অনুমোদন করলে সার্ভার নির্ধারিত নিয়মে কার্যকর হবে।": "The request will be updated only for dates that have not yet been finalised. When the same request is approved, the server will apply it according to its rules.",
    "এই ইমেইল ও নেটওয়ার্কের জন্য Login/Registration সাময়িকভাবে বন্ধ আছে।": "Login/Registration is temporarily unavailable for this email and network.",
    "এই ইমেইল দিয়ে আগে থেকেই একটি অ্যাকাউন্ট রয়েছে।": "An account already exists with this email address.",
    "এই ডিভাইসে অ্যাপটি ইনস্টল করা আছে": "The app is installed on this device",
