    "এই তারিখগুলোর মধ্যে এক বা একাধিক দিনের মিল আগে থেকেই দেওয়া আছে।": "Meals have already been submitted for one or more dates in this range.",
    "এই তারিখের কিছু সদস্যের meal data আগে থেকেই রয়েছে": "Meal data already exists for some members on this date",
    "এই তারিখের জন্য আগে থেকেই একটি মিল রিকোয়েস্ট আছে। আগের রিকোয়েস্টটি এডিট/সংশোধন করুন; নতুন করে একই দিনের request দেবেন না।": "A meal request already exists for this date. Edit or correct the existing request instead of submitting another request for the same day.",
    "এই দিনটি বর্তমান মাসের বাইরে": "This day is outside the current month",
    "এই দিনের অনুরোধ আগে আছে": "A request already exists for this day",
