    "এই দিনের জন্য আপনার একটি লেট অনুরোধ আগে থেকেই জমা হয়েছে। অনুরোধের ইতিহাসে সেটির অবস্থা দেখুন.": "You have already submitted a Late Request for this day. Check its status in Request History.",
    "এই ধাপে মেস-বিহীন account পাওয়া যায়নি। আরও Auth account পরীক্ষা করতে “পরের ধাপ” চাপুন।": "No hostel-free accounts were found in this step. Select “Next step” to check more Auth accounts.",
    "এই নির্দিষ্ট মাসের অনুমোদিত সংশোধন আপনি করতে পারবেন। আপনার বর্তমান Manager পদবি পরিবর্তিত হলেও closed_by রেকর্ডই এই মাসের অধিকার নির্ধারণ করে।": "You can make approved corrections for this specific month. Even if your current Manager role changes, the closed_by record determines your permissions for this month.",
