    "একই অনুরোধে পরিবর্তন হবে": "The existing request will be updated",
    "একই দিনের জন্য আরেকটি অনুরোধ দেওয়া যাবে না। মিল পরিবর্তন করতে অনুরোধের ইতিহাস দেখুন।": "Another request cannot be submitted for the same day. To change a meal, open Request History.",
