    "একই পরিচয়-রেফারেন্সে সর্বশেষ ১৫ মিনিটে:": "For the same identity reference in the last 15 minutes:",
    "একটি আইটেমের নাম সর্বোচ্চ ১৬০ অক্ষরের হতে পারবে।": "An item name can contain up to 160 characters.",
