    "একাধিক running month পাওয়া গেছে। আগে month data যাচাই করুন।": "Multiple running months were found. Verify the month data first.",
    "এখন দেওয়া যাবে": "Available now",
    "এখন বাংলাদেশ সময় রাত ৯টা বা পরে: আজকের চূড়ান্ত মিল অক্ষত থাকবে। আজকের অপেক্ষমাণ লেট/সংশোধন অনুরোধ এবং আগামী দিনের তাঁর সক্রিয় অনুরোধ/মিল রেকর্ড বাতিল হবে; আগের হিসাবও অক্ষত থাকবে।": "At or after 9:00 PM Bangladesh time: today’s finalised meals will remain unchanged. Today’s pending Late/Correction requests and the member’s active requests/meal records for future days will be cancelled; previous accounts will also remain unchanged.",
    "এখন বাংলাদেশ সময় রাত ৯টার আগে: আজকের খোলা মিলের রেকর্ড (থাকলে), আজকের অপেক্ষমাণ লেট/সংশোধন অনুরোধ এবং পরবর্তী সব দিনের তাঁর সক্রিয় অনুরোধ/মিল রেকর্ড বাতিল হবে। আগের দিনের চূড়ান্ত হিসাব অক্ষত থাকবে।": "Before 9:00 PM Bangladesh time: today’s open meal records (if any), today’s pending Late/Correction requests and the member’s active requests/meal records for all future days will be cancelled. Finalised accounts for previous days will remain unchanged.",
