    "এটি মেসভিত্তিক Aggregate রিপোর্ট; সদস্যভিত্তিক ব্যক্তিগত লেনদেন অন্তর্ভুক্ত নয়।": "This is a hostel-level aggregate report; individual member transactions are not included.",
    "এন্ট্রির তারিখ, নাম ও পরিমাণ যাচাই করে হিস্টরি থেকে সংশ্লিষ্ট রেকর্ড খুলুন। যেসব সংশোধন-অপশন আপনার ভূমিকার জন্য দেখানো হয়, শুধু সেগুলো ব্যবহার করুন। প্রয়োজন হলে ম্যানেজারকে কারণসহ জানান; পুরোনো এন্ট্রি গোপনে বদলানো বা ডুপ্লিকেট এন্ট্রি দেবেন না।": "Verify the entry date, name and amount, then open the relevant record from History. Use only the correction options available for your role. Contact the manager with a reason when needed; do not secretly change old entries or create duplicates.",
