    "জরুরি": "Urgent",
    "জরুরি মিল পরিবর্তন": "Urgent meal change",
    "টি অপেক্ষমাণ লেট/সংশোধন অনুরোধ পাওয়া গেছে। নিশ্চিত করলে এগুলো বাতিল হবে; আজ পর্যন্ত অনুমোদিত মিলের হিসাব চূড়ান্ত হবে।": "Pending Late/Correction requests were found. Confirming will cancel them; approved meal accounts through today will be finalised.",
    "টি পুরোনো overlapping normal request pair আছে। এগুলো মাস বন্ধের বাধা নয়; নতুন request দেওয়ার সময় conflict protection কাজ করবে।": "Older overlapping normal request pairs were found. They do not prevent month closure; conflict protection will apply when new requests are submitted.",
    "টি সংরক্ষিত মাস তারিখের পরিসরের সঙ্গে আংশিকভাবে মিলে যাওয়ায় অর্থ ও মিলের পরিমাণ যোগ করা হয়নি। পূর্ণ মাস অন্তর্ভুক্ত করে আবার রিপোর্ট তৈরি করলে সংরক্ষিত সামারি যুক্ত হবে।": "Saved months only partially overlap the selected date range, so their financial and meal totals were not included. Generate the report again with the full months included to add the saved summaries.",
    "টেলিগ্রাম ওয়েবহুক সেট করার পরও নির্ধারিত URL নিশ্চিত করা যায়নি। আবার অবস্থা যাচাই করুন।": "The configured URL could not be confirmed even after setting the Telegram webhook. Check its status again.",
    "টেলিগ্রাম চালু": "Enable Telegram",
    "টেলিগ্রাম বট যাচাই হয়েছে এবং Incoming Webhook সফলভাবে সেট করা হয়েছে।": "The Telegram bot has been verified and the incoming webhook was set successfully.",
    "টেলিগ্রাম বার্তা প্রেরণ বন্ধ করা হয়েছে। বিদ্যমান সংযোগগুলো মুছে ফেলা হয়নি।": "Telegram message delivery has been disabled. Existing connections have not been deleted.",
    "টেলিগ্রাম বার্তা প্রেরণের তালিকা লোড করা যায়নি।": "The Telegram delivery list could not be loaded.",
    "টেলিগ্রাম সংযুক্ত আছে": "Telegram is connected",
    "টেলিগ্রাম সংযোগ লিংক তৈরি করা যায়নি।": "The Telegram connection link could not be created.",
    "টেলিগ্রাম সেটআপ": "Telegram setup",
    "টেলিগ্রাম সেটিংস লোড করা যায়নি।": "Telegram settings could not be loaded.",
    "টেলিগ্রাম সেটিংস সংরক্ষণ করা যায়নি।": "Telegram settings could not be saved.",
    "টেলিগ্রাম সেবা সেটিংস সংরক্ষিত হয়েছে। Edge Function ও Webhook সেটআপ সম্পন্ন না হলে সংযোগ এখনো কাজ করবে না।": "Telegram service settings have been saved. The connection will not work until the Edge Function and webhook setup are complete.",
    "ডাইনিং → “মিল অনুরোধ” → “অনুরোধের ইতিহাস” খুলুন। সংশ্লিষ্ট অনুরোধের বিস্তারিত খুলে “সংশোধনের আবেদন” অপশন থাকলে সেটি ব্যবহার করুন, কারণ লিখুন এবং নতুন মিলের তথ্য দিন। আবেদন কেবল প্রযোজ্য তারিখের সময়সীমায় করা যায় এবং অনুমোদন না হওয়া পর্যন্ত সংশোধিত মিল চূড়ান্ত নয়।": "Open Dining → “Meal Requests” → “Request History”. Open the relevant request details. If “Request correction” is available, select it, enter a reason and provide the updated meal information. Requests can be submitted only within the applicable date window, and corrected meals are not final until approved.",
    "ডাইনিং → “মিল অনুরোধ” → “অনুরোধের ইতিহাস” খুলে সংশ্লিষ্ট তারিখ ও স্ট্যাটাস দেখুন। শুধু বোতাম চাপা বা নোটিফিকেশন দেখা যথেষ্ট নয়; “অনুমোদিত”, “অপেক্ষমাণ” বা “বাতিল” অবস্থা যাচাই করুন।": "Open Dining → “Meal Requests” → “Request History” and check the relevant date and status. Pressing a button or seeing a notification is not enough; verify whether the status is “Approved”, “Pending” or “Cancelled”.",
