    "ড্যাশবোর্ডের “আমার হিসাব” কার্ডে জমা, মোট মিল, মিল খরচ ও অন্যান্য খরচ দেখুন। “বর্তমান বকেয়া” দেখালে ওই পরিমাণ পরিশোধ বাকি; “বর্তমান অবশিষ্ট” দেখালে ওই পরিমাণ জমা/হিসাবের পর অবশিষ্ট আছে। বিস্তারিত বুঝতে কার্ডে নিজের নাম চাপুন।": "On the Dashboard’s “My Accounts” card, review deposits, total meals, meal costs and other expenses. “Current due” means that amount remains to be paid; “Current balance” means that amount remains after deposits and account adjustments. Tap your name on the card to view details.",
