    "নতুন সুবিধা যুক্ত হয়েছে। ব্যবহার সহজ করা হয়েছে। নিরাপত্তা আরও উন্নত করা হয়েছে।": "New features have been added. The experience has been improved, and security has been strengthened.",
    "নাম নেই": "No name",
    "নাম পাওয়া যায়নি": "Name not found",
    "নাম লিখে খুঁজুন…": "Search by name…",
    "নাম সংরক্ষিত নেই": "Name not recorded",
    "নিচের নিশ্চিতকরণ বাক্যটি হুবহু লিখুন।": "Type the confirmation phrase below exactly as shown.",
    "নিচের “প্রোফাইল” ট্যাব খুলুন। “আমার তথ্য” অংশে এডিট চাপুন; নাম ও মোবাইল নম্বর পরিবর্তন করুন। প্রোফাইল ছবির ক্যামেরা বোতাম থেকে JPG, PNG বা WEBP ছবি নির্বাচন করুন। সংরক্ষণ সফল হয়েছে কি না বার্তা দেখে নিশ্চিত করুন।": "Open the “Profile” tab below. Select Edit in “My Information” to change your name and mobile number. Use the camera button on the profile picture to choose a JPG, PNG or WEBP image. Check the confirmation message to make sure it was saved successfully.",
    "নিজেকে নয়": "Not yourself",
    "নিজের তথ্য, পাসওয়ার্ড ও সংযোগ সমস্যার করণীয়।": "Guidance for your information, password and connection issues.",
    "নিজের নামে এন্ট্রি দেওয়ার জন্য fallback দেখানো হতে পারে; অন্য সদস্যের নামে এন্ট্রির আগে তালিকা পুনরায় লোড করুন।": "A fallback may appear for entries under your own name. Reload the list before entering an item under another member’s name.",
