    "নিজের মেস কীভাবে তৈরি করব?": "How do I create my own hostel?",
    "নিবন্ধিত:": "Registered:",
    "নিযুক্ত": "Assigned",
    "নিযুক্ত নেই": "Not assigned",
    "নিরাপত্তার কারণে আপনার লগইন সেশনের নির্ধারিত সময় শেষ হয়েছে। আবার লগইন করে Hostel Life ব্যবহার করুন।": "Your login session expired after reaching its configured duration for security. Sign in again to use Hostel Life.",
    "নিরাপত্তার কারণে এই নেটওয়ার্ক থেকে Login সাময়িকভাবে বন্ধ আছে।": "Login is temporarily blocked from this network for security reasons.",
    "নিরাপত্তার কারণে সেশন বন্ধ করার চেষ্টা করা হয়েছে, কিন্তু এই ডিভাইসের স্থানীয় লগইন পরিষ্কার হয়নি। আবার চেষ্টা করুন।": "A security action attempted to close the session, but the local login on this device could not be cleared. Try again.",
    "নির্দিষ্ট সময়সীমা নেই": "No fixed time limit",
    "নির্ধারিত নয়": "Not scheduled",
    "নির্ধারিত প্রথম মিলের দিন আগামীকালেরও পরে। এই তারিখের আগের রাতে রাত ৮টার পর নতুন মাস চালু করা যাবে।": "The scheduled first meal day is later than tomorrow. The new month can be started after 8:00 PM on the night before that date.",
