    "ডাইনিং → “আমার মিল” বা “মিল অনুরোধ” → “নতুন মিল অনুরোধ” খুলুন। একটি দিন বা তারিখের পরিসর নির্বাচন করে প্রতিদিনের ব্রেকফাস্ট, লাঞ্চ ও ডিনারের মিলের পরিমাণ ঠিক করুন, তারপর জমা দিন। সফল সাধারণ অনুরোধ স্বয়ংক্রিয়ভাবে অনুমোদিত হয়; পরে “অনুরোধের ইতিহাস” থেকে স্ট্যাটাস দেখুন।": "Go to Dining → “My Meals” or “Meal Requests” → “New Meal Request”. Select a day or date range, set the breakfast, lunch and dinner counts for each day, then submit. Successful regular requests are approved automatically. Check the status later under “Request History”.",
    "ডাইনিং → “বাজার এন্ট্রি” খুলুন। বাজারের তারিখ, বাজারকারীর নাম এবং প্রতিটি আইটেম, পরিমাণ ও টাকার অঙ্ক লিখুন। সর্বমোট দেখে সংরক্ষণ করুন। সদস্য সাধারণত নিজের নামে বাজার দিতে পারবেন; ম্যানেজার অনুমতি অনুযায়ী অন্য সদস্যের নামেও এন্ট্রি দিতে পারেন।": "Go to Dining → “Market Entry”. Enter the market date, shopper's name, each item, quantity and amount. Review the total and save. Members can normally submit purchases under their own name; managers may enter purchases for another member when permitted.",
