    "পেস্ট করা লেখায় কোনো আইটেম পাওয়া যায়নি।": "No items were found in the pasted text.",
    "প্রকাশ করা হচ্ছে...": "Publishing...",
    "প্রকাশনার তথ্য লোড করা যায়নি। Run33 Migration প্রয়োগ হয়েছে কি না যাচাই করুন।": "Publication information could not be loaded. Check whether the Run33 migration has been applied.",
    "প্রকাশের আগে অন্তত একটি আপডেট লিখুন।": "Add at least one update before publishing.",
    "প্রকাশের জন্য প্রস্তুত": "Ready to publish",
    "প্রকৃত প্রদানের তারিখ:": "Actual payment date:",
    "প্রক্রিয়াধীন...": "Processing...",
    "প্রতিটি সংশোধনের কারণ ও পরিবর্তন অডিট লগে সংরক্ষিত হবে।": "The reason and changes for each correction will be recorded in the audit log.",
    "প্রতিদিন বাংলাদেশ সময় রাত ৯টায় ওই দিনের মিল ফাইনাল হয়। ফাইনাল হওয়ার পর সদস্য নিজে সাধারণ বা Late/Correction অনুরোধ দিয়ে সেই দিনের হিসাব বদলাতে পারবেন না। অনুমোদিত ম্যানেজারের বিশেষ প্রশাসনিক ক্ষমতা আলাদা নিয়মে কাজ করে।": "Each day's meals are finalised at 9:00 PM Bangladesh time. After finalisation, members cannot change that day's account through regular or Late/Correction requests. Special administrative permissions for authorised managers follow separate rules.",
    "প্রত্যাখ্যাত": "Rejected",
    "প্রথম দিনের মিল অনুরোধ ডাইনিং সেকশন থেকে দেওয়া যাবে।": "The first day's meal request can be submitted from the Dining section.",
    "প্রথম মাস চালু করুন": "Start the first month",
    "প্রথমবার Super Admin খুলতে Authenticator অ্যাপে QR Scan করুন, তারপর ছয় সংখ্যার কোড দিয়ে সংযোগ নিশ্চিত করুন।": "To open Super Admin for the first time, scan the QR code in your authenticator app, then confirm the connection with the six-digit code.",
    "প্রথমে ইন্টারনেট সংযোগ যাচাই করুন। পরে “আবার চেষ্টা করুন” বা “পেজ রিলোড” ব্যবহার করুন। সমস্যা থাকলে ব্রাউজারের Address Bar-এ `https://hostellife-bd.vercel.app/` লিখে সরাসরি ওয়েবসাইট খুলুন। লগআউট করার আগে সমস্যাটি সত্যিই সেশন-সম্পর্কিত কি না নিশ্চিত হোন।": "First check your internet connection. Then select “Try again” or “Reload page”. If the issue remains, enter `https://hostellife-bd.vercel.app/` directly in your browser's address bar. Before signing out, confirm whether the issue is actually related to your session.",
    "প্রথমে এই মাসের সামারি সংরক্ষণ করুন।": "Save this month's summary first.",
    "প্রথমে একটি মেসে যুক্ত হন।": "Join a hostel first.",
    "প্রধান বা সহকারী ম্যানেজারের অনুমোদনের পর আবেদনটি কার্যকর হবে।": "The request will take effect after approval by the primary manager or an assistant manager.",
