    "মেস তৈরির": "Hostel creation",
    "মেস নোটিশ চালু করতে Supabase SQL Editor-এ Run21 মাইগ্রেশন একবার প্রয়োগ করুন।": "To enable hostel notices, apply the Run21 migration once in the Supabase SQL Editor.",
    "মেস নোটিশ ফিচার চালু করতে ডাটাবেস আপডেট প্রয়োজন।": "A database update is required to enable hostel notices.",
    "মেস ম্যানেজার পরিবর্তন": "Change hostel manager",
    "মেস সেটআপ পেজে নেওয়া হচ্ছে...": "Opening hostel setup page...",
    "মেস সেটআপ পেজে “মেস তৈরি করুন” নির্বাচন করে মেসের নাম লিখুন। সিস্টেমে মেস তৈরির অনুমতি-কোড চালু থাকলে সেটিও দিতে হবে। মেস তৈরি হলে আপনি ম্যানেজার হবেন এবং একটি Join Code পাবেন। কোডটি কেবল নির্দিষ্ট সদস্যকে ব্যক্তিগতভাবে দিন—প্রকাশ্যে নয়।": "On the hostel setup page, select “Create a hostel” and enter its name. If hostel creation requires an authorisation code, enter that as well. After creation, you will become the manager and receive a Join Code. Share the code privately with the intended members only—never publicly.",
    "মেস সেটআপ পেজের “অন্য অ্যাকাউন্ট ব্যবহার করুন” বোতাম থেকে বর্তমান ডিভাইসের সেশন বন্ধ করে নতুন অ্যাকাউন্ট দিয়ে লগইন করুন।": "On the hostel setup page, select “Use another account” to end the current device session and sign in with a different account.",
    "মেস সেটিংস কে ব্যবহার করতে পারবেন?": "Who can use Hostel Settings?",
    "মেস সেটিংস থেকে ম্যানেজার বা অনুমোদিত সহকারী নতুন আমন্ত্রণ লিংক তৈরি করে শেয়ার করতে পারবেন। আমন্ত্রিত ব্যক্তি অ্যাকাউন্ট তৈরি করে Join Request পাঠাবেন; অনুমোদনের পরই সদস্যপদ চালু হবে। নতুন লিংক তৈরি করলে আগের লিংক বাতিল হবে।": "Managers or authorised assistants can create and share a new invitation link from Hostel Settings. The invited person must create an account and submit a Join Request; membership becomes active only after approval. Creating a new link invalidates the previous link.",
