    "সদস্য তালিকা সম্পূর্ণভাবে যাচাই করা যায়নি। Auth account মুছতে চাইলে মেসটি আবার নির্বাচন করে সদস্য তালিকা লোড করুন।": "The member list could not be fully verified. To delete an Auth account, select the hostel again and load the member list.",
