    "সহায়তা তথ্য সংরক্ষণ করুন": "Save support information",
    "সাধারণ অনুরোধ, দৈনিক ফাইনাল এবং অনুমোদনের নিয়ম।": "Rules for regular requests, daily finalisation and approvals.",
    "সাধারণ কাট-অফ—আগের দিনের রাত ১০টা—পেরিয়ে গেলে মিলের তারিখের রাত ৯টার ফাইনাল হওয়ার আগ পর্যন্ত Late Request দেওয়া যায়। ডাইনিং → “মিল অনুরোধ” → “লেট অনুরোধ” খুলে তারিখ ও মিলের তথ্য দিন। এটি স্বয়ংক্রিয়ভাবে অনুমোদিত হয় না; ম্যানেজার বা অনুমোদিত সহকারী ম্যানেজারের অনুমোদন লাগবে।": "After the regular cut-off at 10:00 PM on the previous day, you can submit a Late Request until 9:00 PM on the meal date, when that day's meals are finalised. Go to Dining → “Meal Requests” → “Late Request”, then enter the date and meal details. It is not approved automatically; the manager or an authorised assistant manager must approve it.",
    "সাধারণ দিন": "Regular day",
    "সাধারণ মিল অনুরোধ কীভাবে দেব?": "How do I submit a regular meal request?",
    "সাধারণ মিল অনুরোধের শেষ সময় কখন?": "What is the deadline for a regular meal request?",
    "সাধারণ সদস্য হিসাব ইতিহাসে নিজের প্রাসঙ্গিক হিসাব দেখতে পারেন। ম্যানেজার বা অনুমোদিত ব্যবস্থাপনা-ভূমিকা প্রয়োজন অনুযায়ী সদস্য নির্বাচন করে হিসাব দেখতে পারেন। মেসের কিছু বাজার/মিলের রেকর্ড সবার জন্য দৃশ্যমান হতে পারে, তবে সম্পাদনার অনুমতি সীমিত।": "Members can view their own relevant accounts in Account History. Managers and authorised management roles can select members to view their accounts as needed. Some hostel market/meal records may be visible to everyone, but editing permissions are restricted.",
    "সাধারণ সময় শেষ; এখন Late Request পদ্ধতি ব্যবহার করুন, ম্যানেজারের অনুমোদন লাগবে।": "The regular request period has ended. Use the Late Request process; manager approval is required.",
    "সাপ্তাহিক ছুটি": "Weekly day off",
    "সামগ্রিক সারসংক্ষেপ": "Overall summary",
    "সামনের দিনের পরিকল্পনা": "Upcoming plan",
    "সাময়িক বিজ্ঞপ্তি": "Temporary notice",
    "সাময়িক সংযোগ সমস্যার কারণে আজকের মিলের তথ্য আনা যায়নি। আবার চেষ্টা করলে বর্তমান ড্যাশবোর্ডের তথ্য পুনরায় লোড হবে।": "Today's meal information could not be loaded due to a temporary connection issue. Try again to reload the current dashboard data.",
