    "সারসংক্ষেপ যাচাই করা যায়নি।": "The summary could not be verified.",
    "সারসংক্ষেপ যাচাইয়ের অনুমোদন সংরক্ষিত হয়েছে।": "The summary verification approval has been saved.",
    "সারসংক্ষেপ সংরক্ষণ করা যায়নি।": "The summary could not be saved.",
    "সারসংক্ষেপ সংরক্ষণ হয়েছে। মূল হিসাব অপরিবর্তিত রয়েছে।": "The summary has been saved. The original account remains unchanged.",
    "সারাংশ": "Summary",
    "সার্ভার cutoff/finalization যাচাই করে পরিবর্তন প্রয়োগ করবে। কোনো finalized দিনের পরিবর্তন হলে তা audit-সহ final record ও snapshot আপডেট করবে।": "The server will verify the cut-off/finalisation rules before applying changes. If a finalised day is changed, the final record and snapshot will be updated with an audit entry.",
    "সার্ভার অন্য মাসের তথ্য পাঠিয়েছে; নিরাপত্তার জন্য বন্ধ করা হয়েছে।": "The server returned information for another month; this has been blocked for security.",
    "সার্ভার থেকে অস্থায়ী পাসওয়ার্ড পাওয়া যায়নি।": "A temporary password was not received from the server.",
    "সার্ভার থেকে বৈধ Invitation Token পাওয়া যায়নি। Run29 Migration প্রয়োগ হয়েছে কি না যাচাই করুন।": "A valid Invitation Token was not received from the server. Check whether the Run29 migration has been applied.",
    "সার্ভার যাচাইকৃত": "Server verified",
    "সার্ভার সংশোধন নিশ্চিত করেনি।": "The server did not confirm the correction.",
    "সার্ভারে সংরক্ষিত": "Saved on server",
    "সার্ভারের Archive Correction উত্তর সঠিক নয়।": "The server's Archive Correction response is invalid.",
    "সার্ভারের validation-ই চূড়ান্ত; তারিখ/মাস নিশ্চিত না হলে এন্ট্রি দেবেন না।": "Server validation is authoritative; do not submit an entry unless the date/month has been confirmed.",
    "সার্ভারের তথ্য": "Server information",
    "সার্ভারের সংরক্ষিত তথ্য পাওয়া যায়নি। নিরাপত্তার জন্য ফাঁকা ফর্ম দেখানো হচ্ছে না।": "Saved server data could not be retrieved. An empty form is not being shown for security.",
    "সার্ভারের সংরক্ষিত তথ্য লোড না হওয়া পর্যন্ত পরিবর্তন সংরক্ষণ করা যাবে না। আগে আবার লোড করুন।": "Changes cannot be saved until the saved server data has loaded. Load it again first.",
