    "সদস্য, রিপোর্ট, আর্কাইভ, নোটিশ ও পরিচালনার টুলস এক মেনুতে। কোন অপশন দেখা যাবে, তা ব্যবহারকারীর ভূমিকা ও অনুমতির ওপর নির্ভর করে।": "Members, reports, archives, notices and management tools are grouped in one menu. Available options depend on each user’s role and permissions.",
